import type { TheoremEntry } from '../lib/reference-index-file';

export const theoremIndex: TheoremEntry[] = [
  { name: "Identity and dominance laws", statement: "$p \\land \\text{T} \\equiv p$, $\\; p \\lor \\text{F} \\equiv p$, $\\; p \\land \\text{F} \\equiv \\text{F}$, $\\; p \\lor \\text{T} \\equiv \\text{T}$, $\\; p \\lor \\neg p \\equiv \\text{T}$, $\\; p \\land \\neg p \\equiv \\text{F}$.", proof: [], conceptId: "logical-equivalence", domain: "discrete", anchor: "section-theorem-identity-and-dominance-laws" },
  { name: "De Morgan’s laws", statement: "$\\neg(p \\land q) \\equiv (\\neg p) \\lor (\\neg q)$ and $\\neg(p \\lor q) \\equiv (\\neg p) \\land (\\neg q)$.", proofTitle: "Proof by truth table", proof: ["Consider $\\neg(p \\land q)$ and $(\\neg p) \\lor (\\neg q)$ on all four rows.","TT: LHS $\\neg T = F$; RHS $F \\lor F = F$. Agree.","TF: LHS $\\neg F = T$; RHS $F \\lor T = T$. Agree.","FT: LHS $\\neg F = T$; RHS $T \\lor F = T$. Agree.","FF: LHS $\\neg F = T$; RHS $T \\lor T = T$. Agree.","All rows agree, so the formulas are equivalent. The other law is identical."], conceptId: "logical-equivalence", domain: "discrete", anchor: "section-theorem-de-morgans-laws" },
  { name: "Negation rules", statement: "$\\neg \\forall x \\, P(x) \\equiv \\exists x \\, \\neg P(x)$ and $\\neg \\exists x \\, P(x) \\equiv \\forall x \\, \\neg P(x)$.", proofTitle: "Proof by semantics", proof: ["$\\neg \\forall x\\, P(x)$ says \"it is not the case that every x satisfies P\".","That can only fail if at least one x does not satisfy P.","So it is exactly $\\exists x\\, \\neg P(x)$.","The second rule is the same argument with the roles of the quantifiers swapped."], conceptId: "quantifiers", domain: "discrete", anchor: "section-theorem-negation-rules" },
  { name: "Equivalence with contrapositive", statement: "$p \\Rightarrow q \\equiv \\neg q \\Rightarrow \\neg p \\equiv \\neg p \\lor q$.", proofTitle: "Proof", proof: ["By the equivalence $p \\Rightarrow q \\equiv \\neg p \\lor q$ (from the truth table of implication).","Then $\\neg q \\Rightarrow \\neg p \\equiv \\neg(\\neg q) \\lor \\neg p \\equiv q \\lor \\neg p \\equiv \\neg p \\lor q$.","Same normal form, hence equivalent."], conceptId: "implication-converse-inverse", domain: "discrete", anchor: "section-theorem-equivalence-with-contrapositive" },
  { name: "Counting subsets", statement: "If $|A| = n$, then $|\\mathcal{P}(A)| = 2^n$.", proofTitle: "Proof by recursion", proof: ["Let $S_n = |\\mathcal{P}(A)|$ for $|A| = n$.","Fix an element $a \\in A$. Every subset either contains a or does not.","Subsets not containing a are exactly the subsets of $A \\setminus \\{a\\}$: there are $S_{n-1}$ of them.","Subsets containing a are those same subsets with a added: another $S_{n-1}$.","So $S_n = 2 S_{n-1}$ with $S_0 = 1$, giving $S_n = 2^n$."], conceptId: "power-set", domain: "discrete", anchor: "section-theorem-counting-subsets" },
  { name: "Counting functions", statement: "If $|A|=m$ and $|B|=n$ for finite sets, then exactly $n^m$ functions $A \\to B$ exist.", proofTitle: "Proof (independent choices)", proof: ["For the first element of A there are n choices of output.","For the second there are again n choices, independently, and so on for all m inputs.","The product rule gives n × n × ⋯ × n = n^m functions."], conceptId: "function-basics", domain: "discrete", anchor: "section-theorem-counting-functions" },
  { name: "Finite counting criterion", statement: "If $A, B$ are finite and $|A| > |B|$, then no injective $f: A \\to B$ exists.", proofTitle: "Proof (pigeonhole)", proof: ["An injection assigns each of the |A| inputs a distinct output.","There are only |B| distinct outputs available.","If |A| > |B|, by the pigeonhole principle two inputs must share an output — contradiction."], conceptId: "injective-functions", domain: "discrete", anchor: "section-theorem-finite-counting-criterion" },
  { name: "Finite equal-size shortcut", statement: "If $A$ and $B$ are finite with $|A|=|B|$, then $f:A\\to B$ is injective if and only if it is surjective.", proofTitle: "Proof (pigeonhole)", proof: ["If f were injective but missed an element of B, its |A| distinct outputs would fit inside fewer than |B| slots — impossible.","If f were surjective but two inputs shared an output, fewer than |A| distinct outputs would cover all |B| targets — impossible.","Equal finite cardinalities turn either property into the other."], conceptId: "surjective-functions", domain: "discrete", anchor: "section-theorem-finite-equal-size-shortcut" },
  { name: "Equal-size criterion", statement: "If $A, B$ are finite, a bijection $A \\to B$ exists if and only if $|A| = |B|$.", proofTitle: "Idea of proof", proof: ["Injection + equal finite sizes forces surjection (no room for a missed element).","Surjection + equal finite sizes forces injection (no element can be doubled).","Either way, the other property follows from counting."], conceptId: "bijective-functions", domain: "discrete", anchor: "section-theorem-equal-size-criterion" },
  { name: "Composition laws", statement: "Function composition is associative: $h \\circ (g \\circ f) = (h \\circ g) \\circ f$ whenever the types line up. It is generally not commutative.", proofTitle: "Proof", proof: ["For any input a, the left side gives h(g(f(a))).","The right side gives the same nested evaluation h(g(f(a))).","Since the outputs agree for every input, the functions are equal; swapping f and g usually changes which value is fed where."], conceptId: "function-composition", domain: "discrete", anchor: "section-theorem-composition-laws" },
  { name: "Existence", statement: "$f$ has an inverse if and only if $f$ is bijective.", proofTitle: "Proof (sketch)", proof: ["If $f^{-1}$ exists, then $f$ is injective: $f(a)=f(b) \\Rightarrow a = f^{-1}(f(a)) = f^{-1}(f(b)) = b$.","And $f$ is surjective: for any $b$, $a = f^{-1}(b)$ satisfies $f(a)=b$.","Conversely, if $f$ is bijective, define $f^{-1}(b) = $ the unique $a$ with $f(a) = b$ — existence and uniqueness are exactly surjectivity and injectivity."], conceptId: "inverse-functions", domain: "discrete", anchor: "section-theorem-existence" },
  { name: "Composition is associative, and inversion reverses order", statement: "For relations $R \\subseteq A \\times B$, $S \\subseteq B \\times C$, $T \\subseteq C \\times D$: $(T \\circ S) \\circ R = T \\circ (S \\circ R)$ and $(S \\circ R)^{-1} = R^{-1} \\circ S^{-1}$.", proofTitle: "Proof (element chase)", proof: ["Associativity: $(a,d) \\in (T \\circ S) \\circ R$ iff there is $b \\in B$ with $a \\mathrel{R} b$ and $(b,d) \\in T \\circ S$, which itself holds iff there is $c \\in C$ with $b \\mathrel{S} c$ and $c \\mathrel{T} d$.","So $(a,d) \\in (T \\circ S) \\circ R$ iff there exist $b, c$ with $a \\mathrel{R} b$, $b \\mathrel{S} c$, $c \\mathrel{T} d$ — a statement with no parentheses in it.","The same expansion of $(a,d) \\in T \\circ (S \\circ R)$ gives exactly the same existential statement, so the two sets are equal.","Inversion: $(c,a) \\in (S \\circ R)^{-1}$ iff $(a,c) \\in S \\circ R$ iff there is $b$ with $a \\mathrel{R} b$ and $b \\mathrel{S} c$ iff there is $b$ with $c \\mathrel{S^{-1}} b$ and $b \\mathrel{R^{-1}} a$ iff $(c,a) \\in R^{-1} \\circ S^{-1}$. (Matrices: $(M_S M_R)^{\\mathsf{T}} = M_R^{\\mathsf{T}} M_S^{\\mathsf{T}}$.)"], conceptId: "relation-basics", domain: "discrete", anchor: "section-theorem-composition-is-associative-and-inversion-reverses-order" },
  { name: "Transitivity is a closure condition", statement: "A relation $R$ on $A$ is transitive if and only if $R \\circ R \\subseteq R$.", proofTitle: "Proof", proof: ["($\\Rightarrow$) Suppose $R$ is transitive and take $(a,c) \\in R \\circ R$. By definition of composition there is $b$ with $a \\mathrel{R} b$ and $b \\mathrel{R} c$; transitivity gives $a \\mathrel{R} c$, so $(a,c) \\in R$. Hence $R \\circ R \\subseteq R$.","($\\Leftarrow$) Suppose $R \\circ R \\subseteq R$ and take $a \\mathrel{R} b$ and $b \\mathrel{R} c$. Then $(a,c) \\in R \\circ R \\subseteq R$, that is $a \\mathrel{R} c$. So $R$ is transitive. $\\blacksquare$","The matrix form is the same statement: $M \\odot M \\subseteq M$ entrywise, where $\\odot$ is the Boolean product. Squaring a transitive relation changes nothing — which is what lets an algorithm test transitivity by one matrix multiplication instead of $n^3$ pair checks."], conceptId: "relation-properties", domain: "discrete", anchor: "section-theorem-transitivity-is-a-closure-condition" },
  { name: "Symmetric + antisymmetric means “equality-like”", statement: "If $R$ is both symmetric and antisymmetric, then every $a \\mathrel{R} b$ satisfies $a = b$; that is, $R \\subseteq \\{(a,a) : a \\in A\\}$.", proofTitle: "Proof", proof: ["Take any pair $a \\mathrel{R} b$.","By symmetry, $b \\mathrel{R} a$ as well.","Now antisymmetry applies to the two facts $a \\mathrel{R} b$ and $b \\mathrel{R} a$, and concludes $a = b$. $\\blacksquare$","Consequence: on a set with at least two elements, no relation can be both a genuine equivalence relation and a genuine partial order except the equality relation itself — which is why the two families need different hypotheses."], conceptId: "relation-properties", domain: "discrete", anchor: "section-theorem-symmetric-antisymmetric-means-equality-like" },
  { name: "Partitions ↔ equivalence relations", statement: "The equivalence relations on a set $A$ are in one-to-one correspondence with the partitions of $A$.", proofTitle: "Proof", proof: ["Relation → partition: the classes are nonempty by reflexivity; they are disjoint by the argument above; and they cover $A$ because $a \\in [a]$. So they form a partition.","Partition → relation: given a partition $\\{B_i\\}$, define $x \\sim y$ iff $x$ and $y$ lie in the same block. Reflexive (a block contains its members), symmetric (same-block is symmetric), transitive (if $x, y$ share a block and $y, z$ share a block, both blocks contain $y$, so they are the same block and $x, z$ share it).","The two constructions invert each other: classes of the same-block relation are exactly the blocks, and the same-block relation of the classes is the original relation. Since this is a bijection, counting equivalence relations on a finite set equals counting partitions of it. $\\blacksquare$"], conceptId: "equivalence-relations", domain: "discrete", anchor: "section-theorem-partitions-equivalence-relations" },
  { name: "Intersections preserve equivalence; unions do not", statement: "If $\\sim_1$ and $\\sim_2$ are equivalence relations on $A$ then $\\sim_1 \\cap\\, \\sim_2$ is an equivalence relation. The union $\\sim_1 \\cup\\, \\sim_2$ need not be.", proofTitle: "Proof and counterexample", proof: ["Reflexive: every $a$ satisfies $a \\sim_1 a$ and $a \\sim_2 a$, so $a \\sim_1 \\cap\\, \\sim_2 a$. Symmetric and transitive: both properties are “for all” statements that hold for $\\sim_1$ and for $\\sim_2$ separately, so they hold for the conjunction. In fact, any intersection of equivalence relations on $A$ is an equivalence relation.","For the union, take $A = \\{1,2,3\\}$ with classes $\\{\\{1,2\\}, \\{3\\}\\}$ for $\\sim_1$ and $\\{\\{2,3\\}, \\{1\\}\\}$ for $\\sim_2$.","Then $1 \\sim 2$ and $2 \\sim 3$ hold in the union, but $1 \\sim 3$ does not — the union is not transitive. The smallest equivalence relation containing a union is the transitive closure of it, and computing that closure is exactly what union–find does incrementally. $\\blacksquare$"], conceptId: "equivalence-relations", domain: "discrete", anchor: "section-theorem-intersections-preserve-equivalence-unions-do-not" },
  { name: "Linear extension (topological ordering) theorem", statement: "Every finite nonempty poset $(A, \\preceq)$ has a **linear extension**: a total order $\\le$ on $A$ such that $a \\preceq b$ implies $a \\le b$.", proofTitle: "Proof (induction on |A|)", proof: ["Every finite nonempty poset has a minimal element: suppose not, then each element $a$ has some $b \\prec a$; following these strictly descending steps repeats an element (finitely many elements), producing a cycle $x_1 \\prec x_2 \\prec \\cdots \\prec x_1$, which contradicts transitivity and antisymmetry ($x_1 \\prec x_1$ would force $x_1 \\ne x_1$).","Pick a minimal element $m$ and put it first. It is safe: nothing precedes $m$, so no constraint is violated by placing it at the front.","The remainder $A \\setminus \\{m\\}$ is again a finite poset under the restricted order, so by induction it has a linear extension $\\le^{\\prime}$. Define $\\le$ as $m$ first, then $\\le^{\\prime}$.","Any pair $a \\preceq b$ in the original poset is respected: if $a = m$ then $a$ is first, and otherwise both are in the remainder, where the induction hypothesis applies. $\\blacksquare$","The proof is an algorithm: repeatedly extract a minimal element — Kahn’s algorithm with a priority structure, or a DFS that emits vertices in reverse finishing order. The number of linear extensions is a count of schedules, and computing it is #P-hard in general, which is why schedulers count rather than enumerate."], conceptId: "partial-orders", domain: "discrete", anchor: "section-theorem-linear-extension-topological-ordering-theorem" },
  { name: "Knaster–Tarski fixpoint theorem", statement: "Let L be a complete lattice and f : L → L monotone (a ≤ b implies f(a) ≤ f(b)). Then f has a least fixpoint, and it is the least upper bound of the chain ⊥ ≤ f(⊥) ≤ f(f(⊥)) ≤ ⋯.", proofTitle: "Proof sketch", proof: ["Iterate from the bottom: x₀ = ⊥, x_{k+1} = f(x_k). Monotonicity gives x₀ ≤ x₁ by ⊥ being least, and inductively x_k ≤ x_{k+1} — the sequence is a chain.","If the lattice has finite height (every strictly increasing chain is finite, as in any lattice built from finitely many facts), the chain stabilizes after finitely many steps at some x* with f(x*) = x*.","x* is the least fixpoint: any fixpoint y satisfies x₀ = ⊥ ≤ y, and inductively x_k ≤ y (monotone step), so x* ≤ y. Nothing smaller is fixed.","For infinite-height lattices the same argument uses the join of the whole chain instead of stabilization, which is precisely why completeness is assumed: the limit must exist as an element of the lattice."], conceptId: "lattice-logic", domain: "discrete", anchor: "section-theorem-knastertarski-fixpoint-theorem" },
  { name: "Termination by descent", statement: "If every recursive call is on an argument strictly smaller in a well-founded order (one with no infinite strictly descending chain — for example the natural numbers under $<$, strings under length, trees under height), then every computation that follows the definition terminates.", proofTitle: "Proof", proof: ["Suppose some call fails to terminate. Its chain of sub-calls is infinite, so it contains an infinite sequence of arguments $x_0 > x_1 > x_2 > \\cdots$ under the order used by the definition.","Such a chain cannot exist, because the order is well-founded. The supposition is therefore false and every computation terminates.","The same statement has a direct induction form. Assume every call on an argument smaller than $x$ terminates and consider a call on $x$: by hypothesis it makes only strictly smaller calls, so it terminates too. Strong induction covers all $x$.","This is exactly why “it eventually hits the base case” is a proof outline rather than a hope: the decreasing measure is the induction hypothesis in disguise."], conceptId: "recursion", domain: "discrete", anchor: "section-theorem-termination-by-descent" },
  { name: "Structural induction", statement: "Let $P$ be a property of the objects built by a recursive definition. If $P$ holds for every base object, and for every constructor it is preserved — $P$ on the components implies $P$ on the object built from them — then $P$ holds for every object the definition produces.", proofTitle: "Proof (minimal counterexample)", proof: ["Suppose some object fails $P$. Among all objects failing $P$, choose one of minimum size; the collection of sizes is a set of natural numbers, so a minimum exists.","That object is not a base object, since $P$ holds for all base objects. So it was built by a constructor from strictly smaller components.","Each component is smaller than a minimum-size counterexample, so each satisfies $P$. Preservation then forces $P$ on the object itself — a contradiction.","Therefore no counterexample exists, which is the claim."], conceptId: "recursive-definitions", domain: "discrete", anchor: "section-theorem-structural-induction" },
  { name: "Unrolling a divide-and-conquer recurrence", statement: "For $T(n) = a\\,T(n/b) + c\\,n^k$ with $n = b^m$ and $T(1) = \\Theta(1)$, the total is a geometric sum over the levels of the recursion tree: $T(n) = \\sum_{i=0}^{m-1} c\\,n^k\\,(a/b^k)^i + a^m\\,T(1)$, and $a^m = n^{\\log_b a}$.", proofTitle: "Proof (expand and substitute)", proof: ["Level 0 is one problem of size $n$ costing $c\\,n^k$. Expanding once gives $a$ problems of size $n/b$: level 1 costs $a \\cdot c\\,(n/b)^k = c\\,n^k (a/b^k)$.","Expanding $i$ times gives $a^i$ problems of size $n/b^i$, so level $i$ costs $a^i c (n/b^i)^k = c\\,n^k (a/b^k)^i$.","After $m = \\log_b n$ expansions the arguments have reached 1, leaving $a^m$ leaves each costing $T(1)$, and $a^m = a^{\\log_b n} = n^{\\log_b a}$.","Summing the levels gives the stated geometric series. Its ratio $a/b^k$ decides everything: below 1 the series converges, equal to 1 every level counts equally, above 1 the last level dominates."], conceptId: "recurrence-relations", domain: "discrete", anchor: "section-theorem-unrolling-a-divide-and-conquer-recurrence" },
  { name: "Master Theorem", statement: "Let $T(n) = a\\,T(n/b) + \\Theta(n^k)$ with $a \\ge 1$, $b > 1$ and $k \\ge 0$, and let $c^* = \\log_b a$ be the tree’s leaf-growth exponent. Then: case 1, if $k < c^*$ (leaves dominate), $T(n) = \\Theta(n^{c^*})$; case 2, if $k = c^*$ (all levels cost the same), $T(n) = \\Theta(n^k \\log n)$; case 3, if $k > c^*$ (the root dominates), $T(n) = \\Theta(n^k)$.", proofTitle: "Proof (by the recursion tree)", proof: ["By the unrolling lemma, level $i$ of the recursion tree costs $c\\,n^k (a/b^k)^i$, and there are $m = \\log_b n$ levels of internal work.","If $a < b^k$ the ratio is below 1, the geometric series converges to a constant multiple of its first term, so $T(n) = \\Theta(n^k)$ — case 3.","If $a = b^k$ each level costs $c\\,n^k$ and there are $\\log_b n + 1$ levels, giving $\\Theta(n^k \\log n)$ — case 2. The leaves contribute $n^{c^*} = n^k$, the same order as every other level.","If $a > b^k$ the series is dominated by its last internal term $c\\,n^k (a/b^k)^{m} = c\\,a^m = c\\,n^{c^*}$, and the leaves also total $\\Theta(n^{c^*})$, giving $\\Theta(n^{c^*})$ — case 1."], conceptId: "solving-recurrences", domain: "discrete", anchor: "section-theorem-master-theorem" },
  { name: "Binet’s formula", statement: "The Fibonacci numbers satisfy $F_n = \\frac{\\phi^n - \\psi^n}{\\sqrt{5}}$, where $\\phi = \\frac{1+\\sqrt{5}}{2}$ and $\\psi = \\frac{1-\\sqrt{5}}{2}$. In particular $F_n = \\Theta(\\phi^n)$.", proofTitle: "Proof", proof: ["The characteristic equation of $F_n = F_{n-1} + F_{n-2}$ is $r^2 = r + 1$, that is $r^2 - r - 1 = 0$, with roots $\\phi = (1+\\sqrt{5})/2$ and $\\psi = (1-\\sqrt{5})/2$.","So $F_n = \\alpha \\phi^n + \\beta \\psi^n$ for some constants. Use the base values: $F_0 = 0$ gives $\\alpha + \\beta = 0$, and $F_1 = 1$ gives $\\alpha\\phi + \\beta\\psi = 1$.","Substituting $\\beta = -\\alpha$: $\\alpha(\\phi - \\psi) = 1$, and $\\phi - \\psi = \\sqrt{5}$, so $\\alpha = 1/\\sqrt{5}$ and $\\beta = -1/\\sqrt{5}$.","Since $|\\psi| \\approx 0.618 < 1$, the $\\psi^n$ term decays, so $F_n$ is the nearest integer to $\\phi^n/\\sqrt{5}$ — exponential growth with base the golden ratio."], conceptId: "solving-recurrences", domain: "discrete", anchor: "section-theorem-binets-formula" },
  { name: "Three regimes", statement: "With $m = \\log_b n$ levels and $T(1) = \\Theta(1)$, the total work $T(n) = c\\,n^k \\sum_{i=0}^{m-1} (a/b^k)^i + a^m T(1)$ is: $\\Theta(n^k)$ when $a < b^k$, $\\Theta(n^k \\log n)$ when $a = b^k$, and $\\Theta(n^{\\log_b a})$ when $a > b^k$.", proofTitle: "Proof", proof: ["The internal levels form a geometric series with ratio $q = a/b^k$; the leaf level contributes $a^m T(1) = \\Theta(n^{\\log_b a})$.","If $q < 1$, the series converges to $1/(1-q)$ times its first term: internal work is $\\Theta(n^k)$, which is also the largest level, so $T(n) = \\Theta(n^k)$.","If $q = 1$, each of the $m$ levels costs $c\\,n^k$ and the leaves cost $\\Theta(n^k)$ as well: $T(n) = \\Theta(n^k \\log n)$.","If $q > 1$, the series is dominated by its last term $c\\,n^k q^{m-1} = \\Theta(a^m) = \\Theta(n^{\\log_b a})$, matching the leaves: $T(n) = \\Theta(n^{\\log_b a})$."], conceptId: "recursion-trees", domain: "discrete", anchor: "section-theorem-three-regimes" },
  { name: "Last-decision principle (correctness of a DP)", statement: "Suppose every optimal solution of a subproblem $S$ either is a base case or is obtained by extending an optimal solution of some strictly smaller subproblem $S'$, and extending it costs a value that the transition captures exactly. Then the recurrence computes optimal values for every state.", proofTitle: "Proof (induction on state size)", proof: ["Order the states by the size measure that the recurrence decreases. Prove by induction: the recurrence is correct on every state of smaller size.","Base states are handled directly by the base cases. For a non-base state $S$, take an optimal solution $x$ for $S$.","By hypothesis $x$ extends a solution $x'$ of some smaller state $S'$. If $x'$ were not optimal for $S'$, replacing it with an optimal $x^*$ and extending would give a solution for $S$ better than optimal — a contradiction. So $x'$ is optimal for $S'$.","The transition also considers that candidate, so the value it stores is at most the optimum; and every candidate it considers is a feasible solution, so it is at least the optimum. The two bounds meet, so the stored value equals the optimum.","By induction, every state is computed correctly, including the state that represents the original problem."], conceptId: "dynamic-programming", domain: "discrete", anchor: "section-theorem-last-decision-principle-correctness-of-a-dp" },
  { name: "Constants stop mattering — eventually", statement: "If $f \\in o(g)$ — that is, $\\lim_{n\\to\\infty} f(n)/g(n) = 0$ — then for every fixed constant $c > 0$ there is an $n_0$ with $c\\,f(n) < g(n)$ for all $n \\ge n_0$. In words: a better growth rate beats any constant factor, no matter how large, once the input is large enough.", proofTitle: "Proof", proof: ["Fix $c > 0$. By the definition of the limit, $f(n)/g(n) < 1/c$ for all sufficiently large $n$, since the ratio tends to 0.","Multiply both sides by the positive quantity $c\\,g(n)$: $c\\,f(n) < g(n)$.","So the threshold $n_0$ exists for this $c$. The argument never uses the value of $c$, so it works for every constant — including the “10 000× slower machine” factor.","The converse fails, and that is the honest limitation of asymptotics: two algorithms can have the same growth rate and differ by a factor of 100 in practice."], conceptId: "asymptotics", domain: "discrete", anchor: "section-theorem-constants-stop-mattering-eventually" },
  { name: "$\\Theta$ is an equivalence relation", statement: "On the set of positive functions, $\\Theta$ is reflexive, symmetric and transitive, so it partitions functions into growth classes.", proofTitle: "Proof", proof: ["Reflexive: $f \\in \\Theta(f)$ with $c_1 = c_2 = 1$ and $n_0 = 1$.","Symmetric: if $c_1 g(n) \\le f(n) \\le c_2 g(n)$ eventually, then $\\frac{1}{c_2} f(n) \\le g(n) \\le \\frac{1}{c_1} f(n)$ eventually, which is $g \\in \\Theta(f)$.","Transitive: from $f \\in \\Theta(g)$ and $g \\in \\Theta(h)$ with constants $(c_1, c_2)$ and $(d_1, d_2)$ and thresholds $n_1, n_2$, take $n_0 = \\max(n_1, n_2)$ and constants $c_1 d_1$, $c_2 d_2$: $c_1 d_1 h(n) \\le c_1 g(n) \\le f(n) \\le c_2 g(n) \\le c_2 d_2 h(n)$ for $n \\ge n_0$.","The relation is therefore an equivalence relation, and “$f$ and $g$ have the same growth rate” is a well-defined notion rather than a figure of speech."], conceptId: "asymptotic-notation", domain: "discrete", anchor: "section-theorem-theta-is-an-equivalence-relation" },
  { name: "Sum rule", statement: "If $f \\in O(h)$ and $g \\in O(h)$, then $f + g \\in O(h)$. More generally, $f \\in O(h_1)$ and $g \\in O(h_2)$ imply $f + g \\in O(\\max(h_1, h_2))$.", proofTitle: "Proof", proof: ["From $f \\in O(h)$ get $c_1, n_1$ with $f(n) \\le c_1 h(n)$ for $n \\ge n_1$; from $g \\in O(h)$ get $c_2, n_2$.","Let $c = c_1 + c_2$ and $n_0 = \\max(n_1, n_2)$. For $n \\ge n_0$: $f(n) + g(n) \\le c_1 h(n) + c_2 h(n) = c\\,h(n)$.","So $f + g \\in O(h)$ with the explicit constants $(c_1 + c_2, \\max(n_1, n_2))$ — nothing hidden.","For the general form, note $h_1(n) \\le \\max(h_1, h_2)(n)$ and $h_2(n) \\le \\max(h_1, h_2)(n)$ pointwise, so both terms are $O(\\max(h_1, h_2))$ and the previous part applies.","Careful with the last step in general: $\\max(f, g)$ is a perfectly good function, but if $f$ and $g$ are not eventually comparable the max may oscillate between them — the set identity still holds, since the bound is taken pointwise."], conceptId: "asymptotic-properties", domain: "discrete", anchor: "section-theorem-sum-rule" },
  { name: "Product rule", statement: "If $f \\in O(F)$ and $g \\in O(G)$, then $f \\cdot g \\in O(F \\cdot G)$.", proofTitle: "Proof", proof: ["Take $c_1, n_1$ with $f(n) \\le c_1 F(n)$ for $n \\ge n_1$, and $c_2, n_2$ with $g(n) \\le c_2 G(n)$ for $n \\ge n_2$.","All four functions are non-negative, so multiplying the inequalities is legitimate: for $n \\ge \\max(n_1, n_2)$, $f(n) g(n) \\le c_1 c_2 F(n) G(n)$.","Hence $fg \\in O(FG)$ with constant $c_1 c_2$ and threshold $\\max(n_1, n_2)$.","This is the rule you use when the loops are independent: the outer loop contributes its count, the inner body contributes its cost, and the total is the product. If the loops interfere — the inner loop shrinks as the outer advances — you must sum the exact iteration counts instead, as in the triangular double loop."], conceptId: "asymptotic-properties", domain: "discrete", anchor: "section-theorem-product-rule" },
  { name: "Limit test", statement: "For positive $f, g$, let $L = \\lim_{n \\to \\infty} f(n)/g(n)$ (finite or infinite). If $L = 0$ then $f \\in o(g)$; if $0 < L < \\infty$ then $f \\in \\Theta(g)$; if $L = \\infty$ then $g \\in o(f)$.", proofTitle: "Proof", proof: ["Case $0 < L < \\infty$: take $\\epsilon = L/2$. For large $n$, $f(n)/g(n)$ is within $\\epsilon$ of $L$, so $\\frac{L}{2} g(n) \\le f(n) \\le \\frac{3L}{2} g(n)$ — the two inequalities of $\\Theta$ with constants $\\frac{L}{2}$ and $\\frac{3L}{2}$.","Case $L = 0$: for any $c > 0$ there is $n_0$ with $f(n)/g(n) < 1/c$, i.e. $c\\,f(n) < g(n)$, for $n \\ge n_0$. That is the definition of $f \\in o(g)$: every constant multiple of $f$ is eventually below $g$.","Case $L = \\infty$: swap the roles of $f$ and $g$ and apply the second case to $g/f$.","If the limit does not exist, the test is silent — but then the functions are typically incomparable or oscillating, and you must return to the definition with explicit constants."], conceptId: "growth-rates", domain: "discrete", anchor: "section-theorem-limit-test" },
  { name: "Polynomials and exponentials are separated", statement: "If $0 \\le a < b$ then $n^a \\in o(n^b)$. For every fixed $k$, $n^k \\in o(2^n)$. Also $\\log n \\in o(n^{\\epsilon})$ for every $\\epsilon > 0$.", proofTitle: "Proof", proof: ["For the powers: $n^a / n^b = n^{a-b} \\to 0$ because the exponent is negative, so the limit test gives $n^a \\in o(n^b)$.","For the polynomial-exponential gap, compare ratios: $\\frac{2^{n+1}/(n+1)^k}{2^n/n^k} = 2\\left(\\frac{n}{n+1}\\right)^k \\to 2 > 1$, so the ratio $2^n/n^k$ is eventually increasing; since it is positive and increasing it cannot converge to a finite limit, hence $2^n/n^k \\to \\infty$ and $n^k \\in o(2^n)$.","For the logarithm: write $n^{\\epsilon} = e^{\\epsilon \\ln n}$ and $\\ln n = m$. Then $\\ln n / n^{\\epsilon} = m / e^{\\epsilon m} \\to 0$ because the exponential grows faster than any power, so $\\log n \\in o(n^{\\epsilon})$.","The practical consequence: a log factor is cheap, a polynomial factor is expensive, and an exponential factor is fatal — each is eventually overwhelmed by the next."], conceptId: "growth-rates", domain: "discrete", anchor: "section-theorem-polynomials-and-exponentials-are-separated" },
  { name: "The halving bound", statement: "Binary search on a range of n candidates makes at most ⌈log₂ n⌉ comparisons.", proofTitle: "Proof", proof: ["Claim: after $k$ comparisons the surviving interval has at most $\\lceil n / 2^k \\rceil$ candidates. Base case $k = 0$ is immediate.","Inductive step: the current interval has $c$ candidates; the midpoint splits it into two parts of size at most $\\lceil c/2 \\rceil$, and we keep one of them.","So $\\lceil n/2^k \\rceil \\le 1$ once $2^k \\ge n$, i.e. $k \\ge \\log_2 n$; the smallest such integer is $\\lceil \\log_2 n \\rceil$.","The bound is tight for element search: with an adversary answering to keep the answer in the larger half, no strategy can do better, because each comparison has two outcomes and there are $n+1$ possible answers (the $n$ positions plus “absent”). A binary decision tree with $n+1$ leaves has height at least $\\lceil \\log_2(n+1) \\rceil$."], conceptId: "binary-search", domain: "discrete", anchor: "section-theorem-the-halving-bound" },
  { name: "Minterm (sum-of-products) expansion", statement: "Every Boolean function $f: \\{0,1\\}^n \\to \\{0,1\\}$ satisfies $f(x_1, \\ldots, x_n) = \\sum_{v : f(v)=1} m_v$, where the minterm $m_v = y_1 \\cdots y_n$ has $y_i = x_i$ if $v_i = 1$ and $y_i = x_i^{\\prime}$ if $v_i = 0$.", proofTitle: "Proof (check every input)", proof: ["Fix an input vector $u \\in \\{0,1\\}^n$ and look at one minterm $m_v$ with $v \\neq u$.","Some coordinate differs, say $v_i \\neq u_i$; then the literal $y_i$ in $m_v$ is 0 at $u$ (either $x_i = 0$ when $y_i = x_i$, or $x_i = 1$ when $y_i = x_i^{\\prime}$).","A product containing a 0 is 0, so $m_v(u) = 0$. Only $m_u$ itself can be 1 at $u$, and $m_u(u) = 1$ because every literal in it is 1 at $u$.","Hence the OR over all minterms with $f(v) = 1$ evaluates to $f(u)$ at every $u$: the expansion holds. $\\blacksquare$","Consequence: at most $2^n$ minterms, so there are at most $2^{2^n}$ distinct Boolean functions of $n$ variables — and AND-OR-NOT hardware can realize all of them."], conceptId: "boolean-basics", domain: "discrete", anchor: "section-theorem-minterm-sum-of-products-expansion" },
  { name: "De Morgan's laws hold in every Boolean algebra", statement: "In any Boolean algebra, $(a + b)^{\\prime} = a^{\\prime} \\cdot b^{\\prime}$ and $(a \\cdot b)^{\\prime} = a^{\\prime} + b^{\\prime}$.", proofTitle: "Proof (uniqueness of the complement)", proof: ["A complement of $x$ is an element $y$ with $x + y = 1$ and $x \\cdot y = 0$, and it is unique. Indeed if $y$ and $z$ both complement $x$, then $y = y \\cdot 1 = y\\,(x + z) = yx + yz = 0 + yz = yz$, and symmetrically $z = zy = yz$, so $y = z$.","Now check $a^{\\prime} b^{\\prime}$ against $a + b$ directly. Sum: $(a+b) + a^{\\prime}b^{\\prime} = (a + b + a^{\\prime})(a + b + b^{\\prime})$ by distributivity $= (1 + b)(a + 1) = 1 \\cdot 1 = 1$.","Product: $(a+b) \\cdot a^{\\prime}b^{\\prime} = a a^{\\prime} b^{\\prime} + b b^{\\prime} a^{\\prime} = 0 + 0 = 0$.","So $a^{\\prime}b^{\\prime}$ satisfies both complement equations for $a + b$, and by uniqueness it is the complement: $(a+b)^{\\prime} = a^{\\prime}b^{\\prime}$. The second law is the dual (swap $+$ with $\\cdot$ and 0 with 1 everywhere in the argument). $\\blacksquare$","The two-variable truth table is a four-row check, which is why the identity feels obvious: $\\neg(p \\land q)$ and $\\neg p \\lor \\neg q$ differ from $p \\land q$ in exactly the same rows."], conceptId: "de-morgans-laws", domain: "discrete", anchor: "section-theorem-de-morgans-laws-hold-in-every-boolean-algebra" },
  { name: "Functional completeness of {NAND}", statement: "{NAND} is functionally complete: every Boolean function can be built from NAND gates alone. The same holds for {NOR}, and for {AND, OR, NOT}.", proofTitle: "Proof (construct the basis)", proof: ["NOT from NAND: $\\text{NAND}(a,a) = (a \\cdot a)^{\\prime} = a^{\\prime}$ by idempotence.","AND from NAND: $a \\cdot b = \\left(\\text{NAND}(a,b)\\right)^{\\prime} = \\text{NAND}\\big(\\text{NAND}(a,b), \\text{NAND}(a,b)\\big)$ — two gates.","OR from NAND, via De Morgan: $a + b = (a^{\\prime} \\cdot b^{\\prime})^{\\prime} = \\text{NAND}(\\text{NAND}(a,a), \\text{NAND}(b,b))$ — three gates.","Now {AND, OR, NOT} is complete: by the minterm theorem every function is an OR of ANDs of literals. Substitute the NAND constructions above for those three operations and the whole function becomes a NAND network. (The {NOR} case is the dual: swap $+$ with $\\cdot$ and 0 with 1.) $\\blacksquare$","Cost note: the construction is correct but wasteful. XOR needs 4 NANDs, a 4-bit ripple-carry adder around 20, and real designs spend a great deal of effort finding better networks — the existence proof is the easy part."], conceptId: "logic-gates", domain: "discrete", anchor: "section-theorem-functional-completeness-of-nand" },
  { name: "Consensus theorem", statement: "$ab + a^{\\prime}c + bc = ab + a^{\\prime}c$ in any Boolean algebra.", proofTitle: "Proof (algebraic)", proof: ["Work on the left-hand side and expand the extra term: $bc = bc(a + a^{\\prime}) = abc + a^{\\prime}bc$ by distributivity and complement.","So $ab + a^{\\prime}c + bc = ab + a^{\\prime}c + abc + a^{\\prime}bc$.","Now absorb: $ab + abc = ab(1 + c) = ab \\cdot 1 = ab$, and $a^{\\prime}c + a^{\\prime}bc = a^{\\prime}c(1 + b) = a^{\\prime}c$.","Hence the left side equals $ab + a^{\\prime}c$; the reverse inequality is immediate since the left side contains the two surviving terms. $\\blacksquare$","Reading: if $b$ and $c$ are both 1, then either $a$ is 1 (so $ab$ holds) or $a^{\\prime}$ is 1 (so $a^{\\prime}c$ holds). The $bc$ term is never the only reason the function is 1, so it can go."], conceptId: "boolean-simplification", domain: "discrete", anchor: "section-theorem-consensus-theorem" },
  { name: "√2 is irrational", statement: "There are no integers p, q with q ≠ 0 and $\\sqrt{2} = p/q$.", proofTitle: "Proof", proof: ["Assume for contradiction that √2 = p/q with p, q coprime integers, q ≠ 0.","Squaring: 2 = p²/q², so p² = 2q² — hence p² is even, and therefore p is even (an integer square is even iff the integer is even).","Write p = 2k. Then 2q² = p² = 4k², so q² = 2k² — hence q is even too.","But then p and q share the factor 2, contradicting coprimality.","The assumption was false: √2 is irrational."], conceptId: "proof-by-contradiction", domain: "proofs", anchor: "section-theorem-2-is-irrational" },
  { name: "Why induction is valid", statement: "The principle of induction follows from the well-ordering principle: every nonempty subset of ℕ has a least element.", proofTitle: "Proof", proof: ["Suppose some P(n) fails. Let S = { n : P(n) fails } be nonempty.","By well-ordering, S has a least element m ≥ n₀ + 1 (the base case holds).","Then P(m−1) holds, and the inductive step gives P(m) — contradiction.","So S is empty: P(n) holds for all n ≥ n₀."], conceptId: "mathematical-induction", domain: "proofs", anchor: "section-theorem-why-induction-is-valid" },
  { name: "Why the coefficients are C(n, k)", statement: "The coefficient of xᵏ y^{n−k} in (x+y)ⁿ is C(n, k).", proofTitle: "Proof (combinatorial)", proof: ["(x + y)ⁿ is a product of n factors (x + y). Expanding picks x or y from each factor: a term is xᵏ y^{n−k} exactly when x was picked in exactly k of the n factors.","The number of ways to choose which k factors contribute x is C(n, k).","Each such choice contributes the identical monomial xᵏ y^{n−k}, so its total coefficient is C(n, k)."], conceptId: "binomial-theorem", domain: "combinatorics", anchor: "section-theorem-why-the-coefficients-are-cn-k" },
  { name: "The bijection", statement: "Solutions to x₁ + … + xₖ = n biject with placements of k − 1 bars among n + k − 1 positions.", proofTitle: "Proof", proof: ["Write the solution as a row of n stars (the objects) and k − 1 bars (the dividers): **|***|*. The i-th group of stars between consecutive bars is xᵢ.","Placing k − 1 bars in the k − 1 “gaps” among n + k − 1 positions (choose which k−1 of the n + k − 1 slots are bars) is C(n + k − 1, k − 1).","Both constructions invert each other: read off the group sizes, or insert the bars. Bijection proven, count established."], conceptId: "stars-and-bars", domain: "combinatorics", anchor: "section-theorem-the-bijection" },
  { name: "Derangement formula", statement: "$D(n) = n! \\sum_{k=0}^{n} \\frac{(-1)^k}{k!} = \\left\\lfloor \\frac{n!}{e} + \\frac{1}{2} \\right\\rfloor$, and $D(n)/n! \\to 1/e \\approx 0.3679$.", proofTitle: "Proof (inclusion–exclusion)", proof: ["Let Aᵢ = {permutations fixing i}. Count the complement: permutations fixing nothing = n! − |A₁ ∪ … ∪ Aₙ|.","By inclusion–exclusion, |A₁ ∪ … ∪ Aₙ| = ∑ₖ (−1)^{k+1} C(n, k)(n−k)!: choose k fixed points, permute the rest freely.","So D(n) = ∑ₖ (−1)ᵏ C(n, k)(n−k)! = n!∑ₖ (−1)ᵏ/k!. The sum is the truncation of e⁻¹, giving D(n) ≈ n!/e."], conceptId: "derangements", domain: "combinatorics", anchor: "section-theorem-derangement-formula" },
  { name: "Why C(n) counts balanced parentheses", statement: "The number of valid parenthesis strings with n pairs is C(n).", proofTitle: "Proof (reflection principle)", proof: ["Total paths from (0,0) to (2n, 0) with ±1 steps: C(2n, n) (choose the n up-steps).","A path is valid iff it never goes below the axis. Bad paths touch −1: reflect the path from the first −1 onward — a bijection from bad paths to paths from (0,0) to (2n, −2), of which there are C(2n, n−1).","Valid = total − bad = C(2n, n) − C(2n, n−1) = (1/(n+1))C(2n, n) = C(n)."], conceptId: "catalan-numbers", domain: "combinatorics", anchor: "section-theorem-why-cn-counts-balanced-parentheses" },
  { name: "Handshake lemma", statement: "For every undirected graph, $\\sum_{v \\in V} \\deg(v) = 2|E|$.", proofTitle: "Proof (counting edges two ways)", proof: ["Count the pairs (v, e) where v is an endpoint of e.","By vertex: each vertex v contributes deg(v) pairs — total Σ deg(v).","By edge: each edge has exactly two endpoints — total 2|E|.","Same set counted twice: Σ deg(v) = 2|E|. ∎"], conceptId: "degree-and-handshake", domain: "graph-theory", anchor: "section-theorem-handshake-lemma" },
  { name: "Even number of odd-degree vertices", statement: "Every graph has an even number of vertices of odd degree.", proofTitle: "Proof", proof: ["Σ deg(v) = 2|E| is even.","The sum of even degrees is even, so the sum of the odd degrees must be even.","A sum of odd numbers is even iff there are an even number of them."], conceptId: "degree-and-handshake", domain: "graph-theory", anchor: "section-theorem-even-number-of-odd-degree-vertices" },
  { name: "Tree characterizations", statement: "For a graph on n ≥ 1 vertices, the following are equivalent: (1) connected and acyclic; (2) connected with n−1 edges; (3) acyclic with n−1 edges; (4) any two vertices joined by exactly one path.", proofTitle: "Proof (cycle of implications)", proof: ["(1)→(2): take a spanning DFS/BFS tree — it uses n−1 edges (one per non-root vertex), and connectedness gives no more edges than the spanning tree plus… precisely: every non-root vertex contributes exactly one tree edge; an extra edge would form a cycle (contradicting acyclic), so exactly n−1.","(2)→(4): connected gives a path; two distinct paths between u, v would create a cycle, using at least one non-tree edge — but a connected n−1-edge graph has no room for one (adding it gives n edges and a cycle… more directly: a connected graph has a spanning tree of n−1 edges; the whole graph has n−1 edges, so it equals its spanning tree and is a tree: (4) by (1)↔).","(4)→(3): unique paths ⇒ no cycle (a cycle gives two paths). Count edges: sum over vertices of (edges to parent in a BFS tree) = n−1; a further edge would duplicate a path — so n−1 total.","(3)→(1): acyclic n−1-edge graph: adding any missing edge between different components creates no cycle (no path existed) — so it must have exactly one component, i.e. connected. (Equivalently: an acyclic component on k vertices has ≤ k−1 edges, with equality iff connected; summing gives ≤ n − c for c components, so n−1 forces c = 1.)"], conceptId: "trees", domain: "graph-theory", anchor: "section-theorem-tree-characterizations" },
  { name: "Existence", statement: "Every connected graph has a spanning tree.", proofTitle: "Proof", proof: ["Start with all edges; while a cycle exists, remove one edge of that cycle.","Removing a cycle edge never disconnects the graph (the cycle’s other edges still connect its endpoints).","The process ends (edges decrease), leaving a connected, acyclic graph spanning all vertices: a spanning tree.","(Equivalently: run BFS — its tree edges form a spanning tree.)"], conceptId: "spanning-trees", domain: "graph-theory", anchor: "section-theorem-existence" },
  { name: "Cut property", statement: "Let C be any cut of the vertices. The lightest edge crossing C (if unique) belongs to every MST.", proofTitle: "Proof", proof: ["Let e be the unique lightest edge across cut C, and let T be any MST not containing e.","Add e to T: a cycle forms, and that cycle contains another edge f crossing C (it must reconnect the two sides).","By choice of e, w(e) < w(f). Swap: T′ = T − f + e is a spanning tree of smaller weight — contradicting T’s minimality.","So e is in every MST."], conceptId: "minimum-spanning-trees", domain: "graph-theory", anchor: "section-theorem-cut-property" },
  { name: "Euler’s theorem (1736)", statement: "A connected undirected graph has (1) an Euler circuit iff every vertex has even degree; (2) an Euler path (not circuit) iff exactly two vertices have odd degree (the path starts and ends at them).", proofTitle: "Proof (necessity; existence by induction)", proof: ["Necessity: in an Euler circuit, each visit to a vertex consumes one incoming and one outgoing edge — degrees even. In an Euler path, the start and end each have one unpaired edge — odd; internal visits pair up — even.","Existence (0 odd case): induction on E. If the graph is a cycle, done. Otherwise, the even-degree graph has a cycle C; walk C, then for each vertex of C with remaining edges, the leftover subgraph has even degrees and a connected component touching C has an Euler circuit by induction (itself even-degree and connected when restricted) — splice it in at the touch point (Hierholzer’s splicing).","2 odd case: add an artificial edge between the two odd vertices (making all degrees even), take the Euler circuit, and remove the artificial edge — the remainder is the Euler path between them."], conceptId: "euler-paths", domain: "graph-theory", anchor: "section-theorem-eulers-theorem-1736" },
  { name: "Sufficient conditions (Dirac, Ore)", statement: "Dirac: if every vertex has degree ≥ n/2 (n ≥ 3), G is Hamiltonian. Ore: if for every non-adjacent pair u, v, deg(u) + deg(v) ≥ n, G is Hamiltonian.", proof: ["Dirac follows from Ore (non-adjacent u, v have deg(u)+deg(v) ≥ n).","Ore’s proof (sketch): take a longest path P. Its endpoints’ neighbors all lie on P, else P extends. If no endpoint’s neighbor set “crosses” the other endpoint’s, sum the degrees — each neighbor of u pairs with a non-neighbor of v on P — and the Ore bound forces a shortcut that closes a cycle containing all of P; then the degree bound forces the cycle to use all vertices."], conceptId: "hamiltonian-paths", domain: "graph-theory", anchor: "section-theorem-sufficient-conditions-dirac-ore" },
  { name: "Bipartite characterization", statement: "G is bipartite iff it contains no odd cycle.", proofTitle: "Proof", proof: ["If G is bipartite with parts X, Y: any cycle alternates X, Y, X, Y, … and closes only after an even number of steps — no odd cycle.","Conversely, if G has no odd cycle: 2-color each component by BFS (color by distance parity from the root). A bad edge (same-colored endpoints) lies on a walk from the root; its endpoints’ depths have the same parity, so the closed walk formed has odd length — containing an odd cycle, contradiction. So the 2-coloring is valid: G is bipartite."], conceptId: "bipartite-graphs", domain: "graph-theory", anchor: "section-theorem-bipartite-characterization" },
  { name: "Euler’s formula (planar graphs)", statement: "For a connected planar graph with V vertices, E edges, and F faces: $V - E + F = 2$.", proofTitle: "Proof (induction on E)", proof: ["Base: a single vertex, V = 1, E = 0, F = 1 (the outer face): 1 − 0 + 1 = 2.","Step: if the graph has a bridge, remove it — E drops by 1, and two faces merge into one (F drops by 1), V unchanged; V − E + F is invariant, so the formula holds by induction.","If no bridge remains relevant… if the graph has a cycle edge, removing an edge on a cycle merges the two faces it bounded: E − 1, F − 1, V unchanged — again invariant. By induction the smaller graph satisfies the formula, so does the original."], conceptId: "planarity", domain: "graph-theory", anchor: "section-theorem-eulers-formula-planar-graphs" },
  { name: "Correctness (nonnegative weights)", statement: "When a vertex u is settled, dist(u) equals the true shortest-path distance d(s, u).", proofTitle: "Proof (greedy choice / induction)", proof: ["Induction on settling order. s is trivially correct.","Let u be the next settled vertex, and suppose for contradiction that a true shortest path P to u is shorter than dist(u).","P must leave the settled set at some first edge (x, y): x settled, y unsettled. At the moment x was settled, y’s tentative distance became ≤ d(s, x) + w(x, y) = length of P up to y ≤ length(P) < dist(u).","So at the time u was selected, some unsettled vertex y had tentative distance < dist(u) — contradicting the choice of u as the minimum.","Hence u’s settled distance is final. ∎ (Every step of the contradiction uses w(x, y) ≥ 0 — that is where nonnegativity is needed.)"], conceptId: "dijkstra", domain: "graph-theory", anchor: "section-theorem-correctness-nonnegative-weights" },
  { name: "Correctness", statement: "After k rounds, dist(v) ≤ the length of the shortest s–v path using at most k edges (equality holds after |V|−1 rounds, since a simple shortest path has ≤ |V|−1 edges).", proofTitle: "Proof (induction on k)", proof: ["Base k = 0: dist(s) = 0 = best 0-edge path; others ∞.","Step: any shortest path using ≤ k+1 edges has a prefix using ≤ k edges to some u, plus edge (u, v). By the induction hypothesis dist(u) covers the prefix after k rounds, so the (k+1)-st round’s relaxation sets dist(v) to at most the full path length.","After |V|−1 rounds all simple paths are covered: a shortest path with negative edges but no negative cycle is simple (a repeated vertex would contain a cycle of nonnegative total, removable), hence has ≤ |V|−1 edges.","Negative cycle detection: a reachable negative cycle can be traversed arbitrarily many times, so no finite bound on path length exists — the |V|-th round keeps improving, exactly the algorithm’s signal."], conceptId: "bellman-ford", domain: "graph-theory", anchor: "section-theorem-correctness" },
  { name: "Correctness", statement: "After phase k, d[i][j] is the true shortest distance from i to j using intermediates in {1,…,k}.", proofTitle: "Proof (the two-case argument)", proof: ["Consider a shortest i→j path P using intermediates in {1,…,k}.","Case 1: P does not pass through k. Then P is valid in phase k−1, so d^{(k−1)}[i][j] ≤ length(P), and d^{(k)}[i][j] ≤ that.","Case 2: P passes through k. Split at the first (or last) occurrence of k: P = (i → k) + (k → j), both halves using intermediates in {1,…,k−1} (a shortest path is simple, so k appears once… for detection purposes, even with repeats the split works if no negative cycle). By the induction hypothesis each half is ≤ its stored distance, so the second term of the min is ≤ length(P).","In both cases d^{(k)}[i][j] ≤ length(P); the reverse inequality holds because the min only uses real path lengths (no negative cycles). At k = V, all intermediates are allowed: d[i][j] = d(i, j)."], conceptId: "floyd-warshall", domain: "graph-theory", anchor: "section-theorem-correctness" },
  { name: "Max-flow min-cut", statement: "The maximum flow value equals the minimum cut capacity.", proofTitle: "Proof (three inequalities)", proof: ["(a) Any flow’s value ≤ any cut’s capacity: the net flow across cut (S,T) is exactly the flow value, and it is bounded by the sum of the forward capacities (backward flows only reduce it).","(b) Run Ford–Fulkerson to a max flow f; let S be the set of vertices reachable from s in the residual graph. By maximality, no residual edge crosses S→T (else more flow is augmentable), so every original S→T edge is saturated: flow value = cut capacity of (S,T).","(c) Combining: max flow value = capacity(S,T) ≤ min cut capacity ≤ any cut’s capacity ≤ max flow value (by (a)). All equal."], conceptId: "network-flow", domain: "graph-theory", anchor: "section-theorem-max-flow-min-cut" },
  { name: "Max-flow min-cut theorem (Ford–Fulkerson)", statement: "For every flow network, the maximum flow value equals the minimum cut capacity.", proofTitle: "Proof", proof: ["**(Weak duality.)** For any flow f and any cut (S, T), the net flow across the cut equals the value of f: flow is conserved at every internal vertex, so all internal cancellations vanish and only the net s-side outflow survives.","Bound it: net flow across (S,T) is at most the sum of the capacities of edges S → T, because reverse flow subtracts and cannot help. So value(f) ≤ c(S,T) for every f and every cut: max flow ≤ min cut.","**(Achieving equality.)** Run any max-flow algorithm to completion and let f be the result; define S as the set of vertices reachable from s in the residual graph, and T as the rest.","By definition t ∉ S (otherwise another augmenting path exists and f is not maximal), so (S,T) is a cut.","No residual edge goes from S to T — that would make its head reachable. Hence every original edge u → v with u ∈ S, v ∈ T is saturated: f(u,v) = c(u,v).","Also every edge v → u from T to S carries zero flow (else its residual reverse edge would cross S → T). So the net flow across the cut is exactly the sum of the saturated forward capacities: value(f) = c(S,T).","Therefore max flow = value(f) = c(S,T) ≥ min cut, which with weak duality gives equality."], conceptId: "max-flow-min-cut", domain: "graph-theory", anchor: "section-theorem-max-flow-min-cut-theorem-fordfulkerson" },
  { name: "Hall’s marriage theorem", statement: "A bipartite graph with parts L and R has a matching saturating L iff for every subset S ⊆ L, |N(S)| ≥ |S|, where N(S) is the set of neighbours of S.", proofTitle: "Proof sketch (the flow/min-cut route)", proof: ["Build the unit-capacity network: source → each left vertex (capacity 1), each left vertex → each of its neighbours in R (capacity 1), each right vertex → sink (capacity 1).","A matching saturating L exists iff this network has a flow of value |L| (an integral flow decomposes into unit paths, i.e. a matching, and conversely).","By max-flow min-cut, flow |L| is impossible iff some cut has capacity < |L|.","Take any cut (S,T). Let A ⊆ L be left vertices on the sink side and B ⊆ R the right vertices on the source side. The cut’s capacity is |L \\ A| (source edges to A) + |B| (right→sink edges) + edges from L∩S to R\\B that are not present… carefully: an edge from a left vertex in S to a right vertex not in S would cross the cut, but infinite? No — such an edge has capacity 1 and only matters when the head is on the sink side. The minimal choice for a given B forces all left vertices whose neighbours lie inside B to be on the sink side as well; that set is exactly N⁻¹(B).","So the cut capacity is |L| − |S| + |N(S)| for the set S = L \\ A, and it is < |L| precisely when |N(S)| < |S|.","Conclusion: a matching saturating L fails exactly when some S has |N(S)| < |S|. That is Hall’s condition, proved by flow duality."], conceptId: "matching", domain: "graph-theory", anchor: "section-theorem-halls-marriage-theorem" },
  { name: "√2 is irrational", statement: "$\\sqrt{2} \\notin \\mathbb{Q}$.", proofTitle: "Proof (by contradiction)", proof: ["Assume √2 = p/q in lowest terms, p, q ∈ ℤ, q ≠ 0.","Then p² = 2q², so p² even, hence p even (a square is even iff its root is even).","Write p = 2k: then 2q² = 4k², so q² = 2k² and q is even.","But then p and q share a factor of 2, contradicting lowest terms.","So √2 ∉ ℚ. ∎"], conceptId: "number-systems", domain: "number-theory", anchor: "section-theorem-2-is-irrational" },
  { name: "Parity of squares and cubes", statement: "$n^2$ is even iff n is even (and the same for cubes).", proofTitle: "Proof", proof: ["If n = 2k: n² = 4k² — even. If n = 2k+1: n² = 4k² + 4k + 1 = 2(2k² + 2k) + 1 — odd.","So n² even ⇒ n even (contrapositive: n odd ⇒ n² odd). The forward direction is the first line."], conceptId: "parity", domain: "number-theory", anchor: "section-theorem-parity-of-squares-and-cubes" },
  { name: "Division algorithm", statement: "For integers b and a > 0, there exist unique integers q and r with $b = aq + r$ and $0 \\le r < a$. q is the quotient, r the remainder; a | b iff r = 0.", proofTitle: "Proof (existence by well-ordering, uniqueness by size)", proof: ["Existence: consider S = { b − ak : k ∈ ℤ, b − ak ≥ 0 }; it is nonempty (take k negative enough) and has a least element r = b − aq by well-ordering.","If r ≥ a, then r − a = b − a(q+1) ≥ 0 is a smaller element of S — contradiction. So 0 ≤ r < a.","Uniqueness: if b = aq₁ + r₁ = aq₂ + r₂ with both remainders in [0, a), then a(q₁ − q₂) = r₂ − r₁ with |r₂ − r₁| < a. The only multiple of a in (−a, a) is 0, so q₁ = q₂ and r₁ = r₂."], conceptId: "division-algorithm", domain: "number-theory", anchor: "section-theorem-division-algorithm" },
  { name: "Fundamental Theorem of Arithmetic (FTA)", statement: "Every integer n ≥ 2 can be written as a product of primes, and this factorization is unique up to the order of the factors.", proofTitle: "Proof (existence by strong induction; uniqueness by Euclid’s lemma)", proof: ["Existence: strong induction. n = 2 is prime. For n > 2: if n is prime, done; if n = ab with 1 < a, b < n, both factor by the induction hypothesis, so n does.","Euclid’s lemma: if p is prime and p | ab, then p | a or p | b. (Proof: gcd(p, a) is 1 or p. If 1, Bézout gives xp + ya = 1; multiply by b: xpb + yab = b, and p divides both xpb and yab, so p | b — contradiction to p ∤ b. Hence p | a.)","Uniqueness: suppose n = p₁⋯pᵣ = q₁⋯qₛ with all prime. Then p₁ | q₁⋯qₛ, so by the lemma (applied repeatedly) p₁ equals some qⱼ; cancel and induct on the number of factors. So the multisets of primes are equal."], conceptId: "prime-factorization", domain: "number-theory", anchor: "section-theorem-fundamental-theorem-of-arithmetic-fta" },
  { name: "Euclid: infinitely many primes", statement: "There are infinitely many prime numbers.", proofTitle: "Proof (by contradiction)", proof: ["Assume the primes are p₁, p₂, …, pₙ (all of them).","Let N = p₁p₂⋯pₙ + 1. Then N > 1, so N has a prime divisor q (FTA).","If q = pᵢ for some i, then q | N and q | (p₁⋯pₙ), so q | (N − p₁⋯pₙ) = 1 — impossible.","So q is a prime not in the list, contradicting completeness.","Hence the list was never complete: infinitely many primes. ∎"], conceptId: "primes", domain: "number-theory", anchor: "section-theorem-euclid-infinitely-many-primes" },
  { name: "Soundness of Miller–Rabin", statement: "If n is odd composite, at most n − 1 of the bases 1, …, n − 1 are liars; a random base is a witness with probability ≥ 3/4. Running k independent rounds bounds the error by 4^{-k}.", proof: ["The key algebraic fact: in ℤ/nℤ, the equation x² = 1 has at most 4 solutions when n is composite (and exactly 2 when n is prime).","Following the squaring chain from a^d, a “pass” requires hitting 1 or −1 at some point; a composite with many liars would force too many square roots of 1.","Counting roots of x² = 1 over the factorization of n bounds the liars by (n−1)/4 (in fact much fewer for most composites)."], conceptId: "primality-testing", domain: "number-theory", anchor: "section-theorem-soundness-of-millerrabin" },
  { name: "Correctness", statement: "The Euclidean algorithm terminates with gcd(a, b), where the loop is: while b ≠ 0: (a, b) ← (b, a mod b).", proofTitle: "Proof", proof: ["Invariant: gcd(a, b) is unchanged by the step. Indeed gcd(a, b) = gcd(b, a mod b): if a = bq + r, any common divisor of a, b divides r = a − bq, and any common divisor of b, r divides a = bq + r. Same divisor set, same maximum.","Termination: the second component strictly decreases (0 ≤ a mod b < b) and is a nonnegative integer, so it reaches 0 in finitely many steps (well-ordering).","At b = 0, gcd(a, 0) = a — the algorithm’s answer, equal to the original gcd by the invariant."], conceptId: "euclidean-algorithm", domain: "number-theory", anchor: "section-theorem-correctness" },
  { name: "Running time", statement: "The Euclidean algorithm takes at most $5 \\log_{10}(\\min(a,b)) + 1$ divisions — the worst case is consecutive Fibonacci numbers (Fibonacci growth is the slowest possible shrinkage, ratio φ per step).", proof: ["Each step satisfies b_{i+1} ≤ b_i / φ is false in general, but the Fibonacci argument: if b_i < F_{k+2}, then at most k steps remain. The slowest shrink is exactly the Fibonacci recurrence, and F_k ~ φᵏ/√5, giving logarithmic step count."], conceptId: "euclidean-algorithm", domain: "number-theory", anchor: "section-theorem-running-time" },
  { name: "Bézout's identity", statement: "For integers a, b not both zero, there exist integers x, y with $ax + by = \\gcd(a, b)$. The gcd is the smallest positive such linear combination.", proofTitle: "Proof (sketch)", proof: ["Existence: the set S = {xa + yb > 0 : x, y ∈ ℤ} is nonempty and has a least element d = xa + yb by well-ordering.","Show d | a: write a = dq + r, 0 ≤ r < d. Then r = a − dq = a − q(xa + yb) = (1 − qx)a + (−qy)b is a smaller positive element of S unless r = 0. So r = 0 and d | a; similarly d | b.","So d is a common divisor, hence d ≤ gcd(a, b); but any common divisor divides every xa + yb, so gcd(a, b) ≤ d. Thus d = gcd(a, b), with the witness (x, y) in hand."], conceptId: "bezout-identity", domain: "number-theory", anchor: "section-theorem-bezouts-identity" },
  { name: "Congruence is an equivalence relation", statement: "$\\equiv \\pmod n$ is reflexive, symmetric, and transitive.", proofTitle: "Proof", proof: ["Reflexive: n | (a − a) = 0.","Symmetric: n | (a−b) ⇒ n | −(a−b) = (b−a).","Transitive: n | (a−b) and n | (b−c) ⇒ n | [(a−b) + (b−c)] = (a−c)."], conceptId: "congruence", domain: "number-theory", anchor: "section-theorem-congruence-is-an-equivalence-relation" },
  { name: "Existence & uniqueness", statement: "$a$ has a multiplicative inverse mod n iff $\\gcd(a, n) = 1$.", proofTitle: "Proof", proof: ["If ax ≡ 1 (mod n), then n | (ax − 1), so ax − ny = 1 for some y — a Bézout combination, forcing gcd(a, n) = 1.","If gcd(a, n) = 1, Bézout gives ax + ny = 1; mod n this is ax ≡ 1, so x is the inverse.","Uniqueness: if ax ≡ 1 and ax′ ≡ 1, then a(x − x′) ≡ 0; multiplying by a⁻¹… or: n | a(x−x′) and gcd(a, n) = 1 give n | (x − x′)."], conceptId: "modular-inverses", domain: "number-theory", anchor: "section-theorem-existence-uniqueness" },
  { name: "Solvability", statement: "$ax \\equiv b \\pmod n$ has solutions iff $d = \\gcd(a, n)$ divides $b$. If solvable, it has exactly $d$ solutions modulo n.", proofTitle: "Proof", proof: ["ax ≡ b (mod n) ⇔ ax − ny = b for some y (definition of congruence) ⇔ b is a Bézout combination of a, n ⇔ gcd(a, n) | b.","For the count: write a = da′, n = dn′, b = db with gcd(a′, n′) = 1. The congruence becomes a′x ≡ b (mod n′), solvable with the unique solution x₀ mod n′ (invert a′). Lifting back to mod n: the d solutions are x₀, x₀ + n′, x₀ + 2n′, …, x₀ + (d−1)n′."], conceptId: "linear-congruences", domain: "number-theory", anchor: "section-theorem-solvability" },
  { name: "Chinese Remainder Theorem (two moduli)", statement: "If gcd(m, n) = 1, then the system $x \\equiv a \\pmod m$, $x \\equiv b \\pmod n$ has a unique solution modulo $mn$.", proofTitle: "Proof (constructive, via Bézout)", proof: ["Since gcd(m, n) = 1, Bézout gives um + vn = 1.","Claim: x = a·(vn) + b·(um) solves the system.","Mod m: x ≡ a·(vn) (since um ≡ 0 mod m). And vn = 1 − um ≡ 1 (mod m). So x ≡ a (mod m). ✓","Mod n: x ≡ b·(um) and um ≡ 1 (mod n), so x ≡ b (mod n). ✓","Uniqueness mod mn: if x and x′ both solve, m | (x − x′) and n | (x − x′), and coprime m, n give mn | (x − x′)."], conceptId: "chinese-remainder-theorem", domain: "number-theory", anchor: "section-theorem-chinese-remainder-theorem-two-moduli" },
  { name: "Multiplicativity", statement: "If gcd(m, n) = 1, then φ(mn) = φ(m)φ(n).", proofTitle: "Proof (sketch)", proof: ["The CRT gives a bijection ℤ/mnℤ ≅ ℤ/mℤ × ℤ/nℤ.","A class is a unit mod mn iff it is a unit mod m and mod n (a prime dividing mn divides exactly one of m, n).","So units correspond to pairs of units: φ(mn) = φ(m)φ(n)."], conceptId: "euler-totient", domain: "number-theory", anchor: "section-theorem-multiplicativity" },
  { name: "Fermat's Little Theorem", statement: "If p is prime and a is an integer with p ∤ a, then $a^{p-1} \\equiv 1 \\pmod p$. Equivalently, for all a: $a^p \\equiv a \\pmod p$.", proofTitle: "Proof (the permutation argument)", proof: ["Consider the p − 1 numbers a·1, a·2, …, a·(p−1) modulo p.","None is 0 mod p (p ∤ a, and p ∤ k for 1 ≤ k ≤ p−1, and p is prime).","They are all distinct: a·i ≡ a·j (mod p) ⇒ a(i−j) ≡ 0 (mod p) ⇒ p | (i−j) (since p ∤ a) ⇒ i = j, as 1 ≤ i, j ≤ p−1.","So {a·1, …, a·(p−1)} is a permutation of {1, 2, …, p−1} modulo p.","Multiply: a^{p−1}·(p−1)! ≡ (p−1)! (mod p). Since p ∤ (p−1)! (no factor of p in the product), we may “divide” by (p−1)! (it is a unit): a^{p−1} ≡ 1 (mod p). ∎"], conceptId: "fermats-little-theorem", domain: "number-theory", anchor: "section-theorem-fermats-little-theorem" },
  { name: "Euler's theorem", statement: "If $\\gcd(a, n) = 1$, then $a^{\\varphi(n)} \\equiv 1 \\pmod n$.", proofTitle: "Proof (same permutation argument)", proof: ["Let S = {r₁, …, r_{φ(n)}} be the units mod n (the classes coprime to n).","Multiplication by a permutes S: a·rᵢ are distinct units (a unit times a unit is a unit; distinctness by cancellation, which holds for units).","Multiply all elements: a^{φ(n)}·(r₁⋯r_{φ(n)}) ≡ r₁⋯r_{φ(n)} (mod n).","The product R = r₁⋯r_{φ(n)} is itself a unit, so cancel it: a^{φ(n)} ≡ 1 (mod n). ∎"], conceptId: "euler-theorem", domain: "number-theory", anchor: "section-theorem-eulers-theorem" },
  { name: "RSA decrypts correctly", statement: "For 0 ≤ m < n = pq, with ed ≡ 1 (mod φ(n)): (mᵉ)ᵈ ≡ m (mod n).", proofTitle: "Proof", proof: ["ed = 1 + kφ(n) for some k. So (mᵉ)ᵈ = m^{ed} = m·(m^{φ(n)})^k.","If gcd(m, n) = 1: Euler gives m^{φ(n)} ≡ 1 (mod n), so m^{ed} ≡ m·1^k ≡ m (mod n).","If p | m (the other case, since m < pq): then m ≡ 0 (mod p), so m^{ed} ≡ 0 ≡ m (mod p). Mod q: m is invertible, ed ≡ 1 (mod φ(n)) implies ed ≡ 1 (mod q−1) (as q−1 | φ(n)), so by Fermat m^{ed} ≡ m (mod q).","A number ≡ m mod p and ≡ m mod q is ≡ m mod pq = n by CRT. Done — for every m, coprime or not."], conceptId: "rsa-cryptography", domain: "number-theory", anchor: "section-theorem-rsa-decrypts-correctly" },
  { name: "Collision probability (birthday bound)", statement: "With m buckets and k random keys, the collision probability is ≈ 1 − e^{−k(k−1)/(2m)}; it reaches ≈ 0.63 when k ≈ √(2m ln 2) ≈ 1.18√m.", proof: ["P(no collision) = ∏_{i=1}^{k−1} (1 − i/m) ≈ exp(−∑ i/m) = exp(−k(k−1)/(2m)).","Set the exponent to −ln 2: k ≈ √(2m ln 2).","For a 128-bit hash (m = 2¹²⁸), a birthday attack needs ~2⁶⁴ evaluations — the reason hash security is quoted in “birthday bits” (64 for 128-bit digests), not in digest length."], conceptId: "hashing-number-theory", domain: "number-theory", anchor: "section-theorem-collision-probability-birthday-bound" },
  { name: "Bayes' theorem", statement: "For partition {H_i} of Ω, $P(H_j|E)=P(E|H_j)P(H_j)/\\sum_i P(E|H_i)P(H_i)$.", proof: ["By definition $P(H_j|E)=P(H_j∩E)/P(E)$.","Numerator $P(H_j∩E)=P(E|H_j)P(H_j)$ by multiplication rule.","Denominator $P(E)=\\sum_i P(E∩H_i)=\\sum_i P(E|H_i)P(H_i)$ by law of total probability."], conceptId: "bayes-theorem", domain: "probability", anchor: "section-theorem-bayes-theorem" },
  { name: "Linearity of expectation", statement: "$E[aX+bY]=aE[X]+bE[Y]$ even if X,Y dependent. Also $E[\\sum_i X_i]=\\sum_i E[X_i]$.", proof: ["Discrete: E[∑X_i]=∑_ω (∑X_i(ω))P(ω)=∑_i ∑_ω X_i(ω)P(ω)=∑_i E[X_i] by swapping sums.","No independence needed — the sum splits, joint distribution does not matter."], conceptId: "expectation", domain: "probability", anchor: "section-theorem-linearity-of-expectation" },
  { name: "Weak LLN", statement: "If $X_i$ i.i.d. with $E[X]=μ$, $Var<∞$, then $\\bar X_n=\\frac1n\\sum_{i=1}^n X_i \\xrightarrow{P} μ$: for any ε>0, $P(|\\bar X_n-μ|>ε)→0$.", proof: ["Chebyshev: $P(|\\bar X_n-μ|>ε) ≤ Var(\\bar X_n)/ε² = σ²/(nε²) →0."], conceptId: "law-of-large-numbers", domain: "probability", anchor: "section-theorem-weak-lln" },
  { name: "CLT", statement: "If $X_i$ i.i.d., $E[X_i]=μ$, $Var=σ²<∞$, then $\\frac{\\bar X_n-μ}{σ/√n} \\xrightarrow{d} N(0,1)$. Also $\\sum X_i ≈ N(nμ, nσ²)$.", proof: [], conceptId: "central-limit-theorem", domain: "probability", anchor: "section-theorem-clt" },
  { name: "Rank-nullity", statement: "For A m×n: rank(A)+nullity(A)=n. Rank = number pivots in row echelon form.", proof: ["Basis of null space plus basis of row space gives basis of ℝ^n."], conceptId: "rank-nullity", domain: "linear-algebra", anchor: "section-theorem-rank-nullity" },
  { name: "Intermediate Value Theorem", statement: "If f continuous on [a,b] and f(a)<k<f(b) (or vice versa), then ∃c∈(a,b) with f(c)=k.", proof: ["Bisection argument using completeness of ℝ."], conceptId: "continuity", domain: "calculus", anchor: "section-theorem-intermediate-value-theorem" },
  { name: "Product rule", statement: "If $f$ and $g$ are differentiable at $x$, then so is $fg$, and $(fg)'(x) = f'(x)g(x) + f(x)g'(x)$.", proof: ["Add and subtract $f(x+h)g(x)$ in the numerator: $f(x+h)g(x+h) - f(x)g(x) = f(x+h)\\,[g(x+h)-g(x)] + g(x)\\,[f(x+h)-f(x)]$.","Divide by $h$: the quotient is $f(x+h)\\cdot\\frac{g(x+h)-g(x)}{h} + g(x)\\cdot\\frac{f(x+h)-f(x)}{h}$.","As $h\\to 0$: $f(x+h)\\to f(x)$ because differentiable functions are continuous, and the two difference quotients tend to $g'(x)$ and $f'(x)$.","By the limit laws the whole expression tends to $f(x)g'(x) + g(x)f'(x)$. ∎"], conceptId: "differentiation-rules", domain: "calculus", anchor: "section-theorem-product-rule" },
  { name: "Chain rule", statement: "If $g$ is differentiable at $x$ and $f$ is differentiable at $g(x)$, then $f\\circ g$ is differentiable at $x$ with derivative $f'(g(x))\\,g'(x)$.", proof: ["Let $u = g(x)$. Define $\\varphi(k) = \\frac{f(u+k)-f(u)}{k}$ for $k \\neq 0$ and $\\varphi(0) = f'(u)$. Then $\\varphi$ is continuous at $0$ and $f(u+k) - f(u) = \\varphi(k)\\,k$ for every $k$, including $k=0$.","Put $k = g(x+h) - g(x)$. Then $f(g(x+h)) - f(g(x)) = \\varphi(k)\\,[g(x+h)-g(x)]$.","Divide by $h$: $\\frac{f(g(x+h)) - f(g(x))}{h} = \\varphi(k)\\cdot\\frac{g(x+h)-g(x)}{h}$.","As $h \\to 0$, $k \\to 0$ (g is continuous), so $\\varphi(k) \\to f'(u)$, and the second factor tends to $g'(x)$. ∎","The helper $\\varphi$ avoids the classic gap of “multiply and divide by $g(x+h)-g(x)$”, which fails when that difference is zero for small $h$."], conceptId: "differentiation-rules", domain: "calculus", anchor: "section-theorem-chain-rule" },
  { name: "Antiderivatives differ by a constant", statement: "If $F' = G' = f$ on an interval $I$, then there is a constant $C$ with $G(x) = F(x) + C$ for all $x \\in I$.", proof: ["Let $H = G - F$. Then $H'(x) = 0$ for every $x \\in I$.","Take any $a < b$ in $I$. By the Mean Value Theorem there is $c \\in (a,b)$ with $H(b) - H(a) = H'(c)(b-a) = 0$.","So $H(b) = H(a)$ for every pair of points: $H$ is a constant $C$. ∎","The interval hypothesis matters: on $\\mathbb{R}\\setminus\\{0\\}$ the function equal to $0$ for $x<0$ and $1$ for $x>0$ has derivative $0$ but is not constant — which is why $\\int \\frac{1}{x}dx$ can carry a different constant on each side of $0$."], conceptId: "antiderivatives", domain: "calculus", anchor: "section-theorem-antiderivatives-differ-by-a-constant" },
  { name: "Monotone functions are integrable", statement: "If $f$ is increasing on $[a,b]$, then with $n$ equal strips the right sum minus the left sum is exactly $(f(b) - f(a))\\cdot\\frac{b-a}{n}$, which tends to $0$; hence $f$ is integrable.", proof: ["With $\\Delta x = (b-a)/n$: $R_n - L_n = \\Delta x\\sum_{i=1}^n [f(x_i) - f(x_{i-1})]$.","The sum telescopes to $f(x_n) - f(x_0) = f(b) - f(a)$.","For increasing $f$, every Riemann sum over this partition lies between $L_n$ and $R_n$ (each sample value is between its strip's endpoint values).","All sums are squeezed into an interval of width $(f(b)-f(a))(b-a)/n \\to 0$, so they converge to a common limit. ∎"], conceptId: "definite-integral", domain: "calculus", anchor: "section-theorem-monotone-functions-are-integrable" },
  { name: "FTC, Part I", statement: "If $f$ is continuous on $[a,b]$ and $G(x) = \\int_a^x f(t)\\,dt$, then $G$ is differentiable on $(a,b)$ and $G'(x) = f(x)$.", proof: ["For $h > 0$, additivity gives $G(x+h) - G(x) = \\int_x^{x+h} f(t)\\,dt$.","Let $m_h$ and $M_h$ be the minimum and maximum of $f$ on $[x, x+h]$ (they exist because $f$ is continuous). By the bounds property, $m_h h \\le G(x+h)-G(x) \\le M_h h$.","Divide by $h$: $m_h \\le \\frac{G(x+h)-G(x)}{h} \\le M_h$.","As $h \\to 0^+$, continuity of $f$ forces $m_h \\to f(x)$ and $M_h \\to f(x)$. By the squeeze theorem the difference quotient tends to $f(x)$. The case $h<0$ is the same. ∎"], conceptId: "ftoc", domain: "calculus", anchor: "section-theorem-ftc-part-i" },
  { name: "FTC, Part II", statement: "If $f$ is continuous on $[a,b]$ and $F$ is any antiderivative of $f$, then $\\int_a^b f(x)\\,dx = F(b) - F(a)$.", proof: ["By Part I, $G(x) = \\int_a^x f$ is an antiderivative of $f$.","Two antiderivatives on an interval differ by a constant: $F(x) = G(x) + C$.","Then $F(b) - F(a) = (G(b) + C) - (G(a) + C) = G(b) - G(a) = \\int_a^b f - 0$. ∎","The constant cancels, which is why the $+C$ never appears in a definite integral."], conceptId: "ftoc", domain: "calculus", anchor: "section-theorem-ftc-part-ii" },
  { name: "Integration by parts", statement: "If $u, v$ have continuous derivatives on $[a,b]$, then $\\int_a^b u\\,v'\\,dx = [uv]_a^b - \\int_a^b u'\\,v\\,dx$.", proof: ["Product rule: $(uv)' = u'v + uv'$.","Integrate both sides over $[a,b]$ and apply FTC Part II to the left: $[uv]_a^b = \\int_a^b u'v + \\int_a^b uv'$.","Rearrange. ∎"], conceptId: "integration-techniques", domain: "calculus", anchor: "section-theorem-integration-by-parts" },
  { name: "Cheap gradient principle", statement: "If $L:\\mathbb{R}^n\\to\\mathbb{R}$ is computed by a graph with $E$ edges, reverse mode computes all $n$ partial derivatives with $O(E)$ operations — independent of $n$ beyond the cost of evaluating $L$ itself.", proof: ["Order the nodes topologically and run the forward pass, storing each value; this costs $O(E)$.","Set $\\bar L = 1$ and visit nodes in reverse topological order. When a node $c$ is visited, its adjoint is final, because every node that depends on it has already been visited.","For each edge $v \\to c$, add $\\bar c\\cdot\\partial c/\\partial v$ into $\\bar v$. The local derivative is $O(1)$ from stored values, so each edge is processed once at $O(1)$ cost.","By the graph chain rule the accumulated $\\bar v$ equals $\\partial L/\\partial v$ for every node, inputs included. Total work $O(E)$. ∎"], conceptId: "differentiation-rules-calc", domain: "calculus", anchor: "section-theorem-cheap-gradient-principle" },
  { name: "Lagrange", statement: "If H≤G finite, |H| divides |G|. Number of cosets [G:H]=|G|/|H|.", proof: ["Cosets partition G, each size |H|."], conceptId: "subgroups", domain: "abstract-algebra", anchor: "section-theorem-lagrange" },
  { name: "Source coding theorem", statement: "For i.i.d. X^n with entropy H, for any ε>0, ∃ code with expected length ≤ n(H+ε) for large n, and no code can achieve expected length < n(H-ε) (asymptotically).", proof: ["Typical set has ≈2^{nH} sequences, each ~2^{-nH} probable; need nH bits to index them. Atypical set negligible."], conceptId: "compression", domain: "information-theory", anchor: "section-theorem-source-coding-theorem" },
  { name: "Halting undecidable", statement: "No TM H decides HALT = {<M,w> | M halts on w}.", proof: ["Assume H decides HALT. Build D that on input <M>: run H(<M,<M>>); if H says halts, loop forever; else halt.","Consider D(<D>): if D halts on <D>, then H(<D,<D>>)=halts, so D loops — contradiction. If D loops on <D>, then H says loops, so D halts — contradiction.","Hence H cannot exist."], conceptId: "halting-problem", domain: "formal", anchor: "section-theorem-halting-undecidable" },
];
